            rotated->x = 0.0;
            rotated->y = 0.0;
            rotated->z = 0.0;
        }
        return ADCS_E_NULL;
    }

    /* 2. Finite check */
    if ((!adcs_is_finite_vec3(vector)) || (!adcs_is_finite_vec3(axis)) || (!isfinite(angle_rad))) {
        rotated->x = 0.0;
        rotated->y = 0.0;
        rotated->z = 0.0;
        return ADCS_E_RANGE;
    }

    /* 3. Normalize axis and check for zero vector */
    if (adcs_vec3_normalize(axis, FLT64_ZERO, &u) != ADCS_OK) {
        rotated->x = 0.0;
        rotated->y = 0.0;
        rotated->z = 0.0;
        return ADCS_E_RANGE;
    }

    /* 4. Precompute trig functions */
    cos_a = cos(angle_rad);
    sin_a = sin(angle_rad);
    one_minus_cos_a = 1.0 - cos_a;

    /* 5. Compute dot product: u . v */
    dot_uv = adcs_vec3_dot(&u, vector);

    /* 6. Compute cross product: u x v */
    term2 = adcs_vec3_cross(&u, vector);

    /* 7. Term 1: v * cos(a) */
    term1 = adcs_vec3_scale(vector, cos_a);

    /* 8. Term 2: (u x v) * sin(a) */
    term2 = adcs_vec3_scale(&term2, sin_a);

    /* 9. Term 3: u * (u . v) * (1 - cos(a)) */
    term3 = adcs_vec3_scale(&u, dot_uv * one_minus_cos_a);

    /* 10. Sum terms: v' = term1 + term2 + term3 */
    *rotated = adcs_vec3_add(&term1, &term2);
    *rotated = adcs_vec3_add(rotated, &term3);

    return ADCS_OK;
}

